consignas.comienza:
int main() {
  int n;

  scanf("%d", &n);
  int *v = malloc(n * sizeof(int));
  int suma = 0;

  for (int i = 0; i <= n; i++) {
    scanf("%d", &v[i]);
    suma += v[i];
  }
  printf("Suma: %d", suma);
  free(v);
  return 0;
}

